265	static const health_hist_t *hist_n_back(int n)
266	{
267	    int idx;
268	
269	    if (s_hist_count == 0) {
270	        return NULL;
271	    }
272	    if (n >= s_hist_count) {
273	        n = s_hist_count - 1;
