#!/usr/bin/env python3
"""Small HIL helper for the edge health subsystem.

  hil_probe.py show [n]          print n snapshots at 2 s spacing
  hil_probe.py watch [seconds]   print one compact line every 2 s
  hil_probe.py inject '<json>'   POST /api/health/fault
  hil_probe.py ack               POST /api/health/ack
"""

import json
import sys
import time
import urllib.request

BASE = "http://192.168.223.2:28789/api/health"


def get():
    with urllib.request.urlopen(BASE, timeout=6) as r:
        return json.load(r)


def post(url, body):
    req = urllib.request.Request(
        url, data=json.dumps(body).encode(), method="POST",
        headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=6) as r:
        return r.read().decode()


def issues(d):
    return ",".join("%s/%s" % (i["code"], i["severity"])
                    for i in d["issues"]) or "-"


def line(d):
    b = d["beats"]
    return (
        "up=%-4d %-8s issues=%-34s boot=%d auto=%d safe=%s "
        "mic(w=%d r=%d rs=%d age=%sms err=%d) ws(cl=%d fail=%d to=%d) "
        "beat(out=%s idle=%s net=%s cron=%s acc=%s mic=%s lvgl=%s)"
        % (d["uptime"], d["status"], issues(d), d["boot_count"],
           d["auto_reset_count"], d["safe_mode"],
           d["mic"]["want"], d["mic"]["running"], d["mic"]["restarts"],
           d["mic"]["last_frame_age_ms"], d["mic"]["read_errors"],
           d["ws"]["clients"], d["ws"]["tx_fail"], d["ws"]["tx_timeout"],
           b["outbound"], b["agent_idle"], b["net"], b["cron"],
           b["ws_accept"], b["mic"], b["lvgl"]))


def main():
    cmd = sys.argv[1] if len(sys.argv) > 1 else "show"

    if cmd == "inject":
        body = json.loads(sys.argv[2])
        print("POST", body, "->", post(BASE + "/fault", body))
    elif cmd == "ack":
        print("ack ->", post(BASE + "/ack", {}))
    elif cmd == "show":
        n = int(sys.argv[2]) if len(sys.argv) > 2 else 1
        for i in range(n):
            try:
                print(line(get()))
            except Exception as exc:
                print("ERR", type(exc).__name__, exc)
            if i + 1 < n:
                time.sleep(2)
    elif cmd == "watch":
        secs = int(sys.argv[2]) if len(sys.argv) > 2 else 60
        end = time.time() + secs
        while time.time() < end:
            try:
                print(line(get()))
            except Exception as exc:
                print("ERR", type(exc).__name__, exc)
            time.sleep(2)
    else:
        print(__doc__)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())

