#!/usr/bin/env python3
"""Check which characters used by the LVGL UI have a glyph in the CJK font."""

import re
import sys

FONT = ("//wsl.localhost/Ubuntu-26.04/home/Oliweitz/openvela/packages/ai_agent/"
        "src/ui/fonts/lv_font_misans_18_cjk.c")
SRC = ("//wsl.localhost/Ubuntu-26.04/home/Oliweitz/openvela/packages/ai_agent/"
       "src/ui/lvgl_ui_channel.c")


def arrays(text, name):
    """Return {array_name: [ints]} for static const uint16_t name[] blocks."""
    out = {}
    pat = re.compile(
        r"static\s+const\s+uint16_t\s+" + name + r"(\d+)\[\]\s*=\s*\{([^}]*)\}")
    for m in pat.finditer(text):
        vals = []
        for tok in m.group(2).replace("\n", " ").split(","):
            tok = tok.strip()
            if not tok:
                continue
            vals.append(int(tok, 0))
        out[m.group(1)] = vals
    return out


def parse_cmaps(text, ulists, ofslists):
    cov = set()
    # Join each cmap entry into one line-ish chunk.
    for m in re.finditer(
            r"\.range_start\s*=\s*(\d+),\s*\.range_length\s*=\s*(\d+),\s*"
            r"\.glyph_id_start\s*=\s*(\d+),\s*"
            r"\.unicode_list\s*=\s*([A-Za-z0-9_]+),\s*"
            r"\.glyph_id_ofs_list\s*=\s*([A-Za-z0-9_]+),\s*"
            r"\.list_length\s*=\s*(\d+),\s*"
            r"\.type\s*=\s*([A-Za-z0-9_]+)", text):
        start, length = int(m.group(1)), int(m.group(2))
        uname, oname = m.group(4), m.group(5)
        typ = m.group(7)
        if typ == "LV_FONT_FMT_TXT_CMAP_FORMAT0_TINY":
            cov.update(range(start, start + length))
        elif typ == "LV_FONT_FMT_TXT_CMAP_FORMAT0_FULL":
            ofs = ofslists.get(oname[15:], [])  # glyph_id_ofs_list_N
            for i, v in enumerate(ofs[:length]):
                if v != 0xFFFF:
                    cov.add(start + i)
        elif typ == "LV_FONT_FMT_TXT_CMAP_SPARSE_TINY":
            ul = ulists.get(uname[13:], [])  # unicode_list_N
            for v in ul:
                cov.add(start + v)
        elif typ == "LV_FONT_FMT_TXT_CMAP_SPARSE_FULL":
            ul = ulists.get(uname[13:], [])
            for v in ul:
                cov.add(start + v)
    return cov


def string_chars(path):
    text = open(path, encoding="utf-8").read()
    out = {}
    i = 0
    line = 1
    in_str = False
    esc = False
    while i < len(text):
        ch = text[i]
        if ch == "\n":
            line += 1
        if not in_str:
            if ch == '"':
                in_str = True
            i += 1
            continue
        if esc:
            esc = False
            i += 1
            continue
        if ch == "\\":
            esc = True
            i += 1
            continue
        if ch == '"':
            in_str = False
            i += 1
            continue
        if ord(ch) >= 128:
            out.setdefault(ch, line)
        i += 1
    return out


def main():
    font_text = open(FONT, encoding="utf-8").read()
    ulists = arrays(font_text, "unicode_list_")
    ofslists = arrays(font_text, "glyph_id_ofs_list_")
    cov = parse_cmaps(font_text, ulists, ofslists)
    print("font coverage codepoints:", len(cov))

    chars = string_chars(SRC)
    print("non-ASCII chars in UI strings:", len(chars))
    missing = [(ch, line) for ch, line in chars.items() if ord(ch) not in cov]
    if not missing:
        print("ALL COVERED")
        return 0
    for ch, line in sorted(missing, key=lambda x: x[1]):
        print("MISSING line %d U+%04X %r" % (line, ord(ch), ch))
    return 1


if __name__ == "__main__":
    sys.exit(main())

