#!/usr/bin/env python3
"""Retry the LLM mode API around the device's intermittent HTTP stalls."""

import json
import time
import urllib.request

BASE = "http://192.168.223.2:28789"


def get(path, retries=15):
    last = None
    for _ in range(retries):
        try:
            with urllib.request.urlopen(BASE + path, timeout=6) as r:
                return r.read().decode()
        except Exception as exc:
            last = exc
            time.sleep(2)
    raise last


def post(path, body, retries=15):
    last = None
    for _ in range(retries):
        try:
            req = urllib.request.Request(
                BASE + path, data=json.dumps(body).encode(), method="POST",
                headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=8) as r:
                return r.read().decode()
        except Exception as exc:
            last = exc
            time.sleep(2)
    raise last


