#!/usr/bin/env python3
"""Verify the body-less LLM mode switch used by the settings-page button."""

import json
import time
import urllib.request

BASE = "http://192.168.223.2:28789"


def call(path, method="GET", retries=20):
    last = None
    for _ in range(retries):
        try:
            req = urllib.request.Request(
                BASE + path,
                data=b"" if method == "POST" else None,
                method=method)
            with urllib.request.urlopen(req, timeout=6) as r:
                return r.read().decode()
        except Exception as exc:
            last = exc
            time.sleep(2)
    raise last


def model():
    try:
        return json.loads(call("/api/config")).get("model")
    except Exception as exc:
        return "config? " + type(exc).__name__


print("start  :", call("/api/llm/mode"), "config model:", model())
